Refactor this nested switch-based workflow into a clearer state-machine-style structure while preserving transitions and outputs.

function processOrder(order) {
  switch (order.status) {
    case 'new':
      if (!order.paymentId) { order.status = 'awaiting_payment'; break; }
      order.status = 'paid';
      // fallthrough
    case 'paid':
      if (order.items.some(i => !i.inStock)) {
        order.status = 'backorder'; order.backorderAt = Date.now(); break;
      }
      order.status = 'picking';
      // fallthrough
    case 'picking':
      if (!order.assignedPicker) { assignPicker(order); break; }
      if (!order.pickedAt) break;
      order.status = 'shipping';
      // fallthrough
    case 'shipping':
      if (!order.trackingNumber) { requestShipment(order); break; }
      if (order.deliveredAt) { order.status = 'delivered'; break; }
      break;
    case 'backorder':
      if (Date.now() - order.backorderAt > 86400000) {
        notifyCustomer(order, 'delay');
        if (Date.now() - order.backorderAt > 604800000) {
          order.status = 'cancelled'; refund(order); break;
        }
      }
      if (order.items.every(i => i.inStock)) { order.status = 'paid'; return processOrder(order); }
      break;
    default: throw new Error('Unknown status: ' + order.status);
  }
  return order;
}

