function analyze(records) {
  const r = records.filter(x => x.active && x.ts > Date.now() - 86400000 && x.type !== 'internal');
  const groups = {};
  for (let i = 0; i < r.length; i++) {
    const k = r[i].region + ':' + r[i].tier;
    if (!groups[k]) groups[k] = { items: [], sum: 0, min: Infinity, max: -Infinity, count: 0 };
    groups[k].items.push(r[i]);
    groups[k].sum += r[i].value;
    groups[k].min = Math.min(groups[k].min, r[i].value);
    groups[k].max = Math.max(groups[k].max, r[i].value);
    groups[k].count++;
  }
  const result = [];
  for (const k in groups) {
    const g = groups[k];
    const avg = g.sum / g.count;
    const variance = g.items.reduce((s, x) => s + Math.pow(x.value - avg, 2), 0) / g.count;
    const outliers = g.items.filter(x => Math.abs(x.value - avg) > 2 * Math.sqrt(variance));
    const [region, tier] = k.split(':');
    result.push({ region, tier, avg: Math.round(avg * 100) / 100, min: g.min, max: g.max, count: g.count, stdDev: Math.round(Math.sqrt(variance) * 100) / 100, outlierCount: outliers.length, topOutlier: outliers.sort((a, b) => b.value - a.value)[0] || null });
  }
  return result.sort((a, b) => b.count - a.count);
}

