This pipeline has a rare nondeterministic bug: under high load, final stats are occasionally wrong and some batches silently drop. Provide systematic diagnosis, likely root causes, and minimal fix.

class Pipeline {
  constructor(workers = 8, batchTimeout = 5000) {
    this.workers = workers;
    this.batchTimeout = batchTimeout;
    this.stats = { processed: 0, errors: 0, dropped: 0 };
    this.activeBatches = new Map();
  }
  async run(inputStream) {
    const batches = this.toBatches(inputStream, 100);
    const pool = [];
    for await (const batch of batches) {
      const batchId = Date.now() + '-' + Math.random().toString(36).slice(2, 6);
      this.activeBatches.set(batchId, { startedAt: Date.now(), size: batch.length });
      const work = this.processBatch(batchId, batch);
      pool.push(work);
      if (pool.length >= this.workers) {
        await Promise.race(pool);
        // remove settled promises
        for (let i = pool.length - 1; i >= 0; i--) {
          const status = await Promise.race([pool[i].then(() => 'done'), Promise.resolve('pending')]);
          if (status === 'done') pool.splice(i, 1);
        }
      }
    }
    await Promise.allSettled(pool);
    return this.stats;
  }
  async processBatch(batchId, items) {
    const timer = setTimeout(() => {
      this.stats.dropped += this.activeBatches.get(batchId)?.size || 0;
      this.activeBatches.delete(batchId);
    }, this.batchTimeout);
    try {
      for (const item of items) {
        const result = await this.transform(item);
        if (result.error) { this.stats.errors++; continue; }
        this.stats.processed++;
      }
    } catch (err) {
      this.stats.errors += items.length;
    } finally {
      clearTimeout(timer);
      this.activeBatches.delete(batchId);
    }
  }
  async transform(item) {
    await sleep(Math.random() * 100);
    if (Math.random() < 0.01) throw new Error('transient');
    return { data: item.value * 2 };
  }
}
